toolCalls.args:
{"command": "# Those addresses fall into a jump table (computed goto labels) within mono_interp_exec_method
# Let's find the actual code functions by looking at nearby code symbols
DBG="/tmp/symbols/libmonosgen-2.0.so.dbg"
readelf -sW "$DBG" 2>/dev/null | awk '$2 != "0" && $3 != "0" && $4 == "FUNC"' | awk '{
  addr = strtonum("0x"$2); size = strtonum("0x"$3)
  if (addr <= 0x2f4b20 && addr+size > 0x2f4b20) print "0x2f4b20 in:", $8, "(at 0x"$2", size "$3")"
  if (addr <= 0x2f4c84 && addr+size > 0x2f4c84) print "0x2f4c84 in:", $8, "(at 0x"$2", size "$3")"
}'", "description": "Find enclosing functions for SGen addresses"}

arguments.command:
# The addresses are in a data section (jump table for the interpreter). Let's look for
# the actual function that contains these - likely sgen_workers_thread_func or similar
# Let me check if these PCs might be slightly off - on ARM64 the return address might need -4
DBG="/tmp/symbols/libmonosgen-2.0.so.dbg"

# Actually let's just check what functions are near these addresses
readelf -sW "$DBG" | awk '$4 == "FUNC"' | awk '{addr=strtonum("0x"$2); size=strtonum("0x"$3); printf "%s %d %d\n", $8, addr, size}' | awk -v t1=0x2f4b20 -v t2=0x2f4c84 '
BEGIN { t1=strtonum(t1); t2=strtonum(t2); best1_diff=999999999; best2_diff=999999999 }
{ addr=$2; size=$3; name=$1
  if (addr <= t1 && (t1-addr) < best1_diff) { best1_diff=t1-addr; best1=name; best1_addr=addr; best1_size=size }
  if (addr <= t2 && (t2-addr) < best2_diff) { best2_diff=t2-addr; best2=name; best2_addr=addr; best2_size=size }
}
END {
  printf "0x2f4b20: nearest func = %s (addr=0x%x, size=%d, offset=+0x%x, %s)\n", best1, best1_addr, best1_size, best1_diff, (best1_diff < best1_size ? "WITHIN" : "OUTSIDE")
  printf "0x2f4c84: nearest func = %s (addr=0x%x, size=%d, offset=+0x%x, %s)\n", best2, best2_addr, best2_size, best2_diff, (best2_diff < best2_size ? "WITHIN" : "OUTSIDE")
}'

